 39	func NewRunCommand() (*RunCommand, error) {
 40		glazedLayer, err := schema.NewGlazedSchema()
 41		if err != nil {
 42			return nil, err
 43		}
 44		commandSettingsLayer, err := cli.NewCommandSettingsLayer()
 45		if err != nil {
 46			return nil, err
 47		}
 48	
 49		cmdDesc := cmds.NewCommandDescription(
 50			"run",
 51			cmds.WithShort("Run css-visual-diff capture and analysis modes"),
 52			cmds.WithLong("Run css-visual-diff using a YAML capture plan and one or more modes."),
 53			cmds.WithFlags(
 54				fields.New(
 55					"config",
 56					fields.TypeString,
 57					fields.WithHelp("Path to css-visual-diff YAML config"),
 58				),
 59				fields.New(
 60					"modes",
 61					fields.TypeString,
 62					fields.WithDefault(""),
 63					fields.WithHelp("Comma-delimited list of modes (capture,cssdiff,matched-styles,ai-review,full)"),
 64				),
 65				fields.New(
 66					"dry-run",
 67					fields.TypeBool,
 68					fields.WithDefault(false),
 69					fields.WithHelp("Validate config and modes without running browser actions"),
 70				),
 71				fields.New(
 72					"pixeldiff-threshold",
 73					fields.TypeInteger,
 74					fields.WithDefault(30),
 75					fields.WithHelp("Pixel diff threshold (0-255) used by pixeldiff mode"),
 76				),
 77			),
 78			cmds.WithLayersList(glazedLayer, commandSettingsLayer),
 79		)
 80	
 81		return &RunCommand{CommandDescription: cmdDesc}, nil
