 84	func (c *RunCommand) RunIntoGlazeProcessor(
 85		ctx context.Context,
 86		vals *values.Values,
 87		gp middlewares.Processor,
 88	) error {
 89		settings := &RunSettings{}
 90		if err := values.DecodeSectionInto(vals, schema.DefaultSlug, settings); err != nil {
 91			return err
 92		}
 93		if settings.Config == "" {
 94			return fmt.Errorf("--config is required")
 95		}
 96	
 97		cfg, err := config.Load(settings.Config)
 98		if err != nil {
 99			return err
100		}
101	
102		modesRaw := settings.Modes
103		if modesRaw == "" && len(cfg.Modes) > 0 {
104			modesRaw = joinModes(cfg.Modes)
105		}
106	
107		modesList, err := runner.NormalizeModes(modesRaw)
108		if err != nil {
109			return err
110		}
111	
112		result, err := runner.Run(ctx, cfg, modesList, settings.DryRun, runner.RunOptions{
113			PixelDiffThreshold: settings.PixelDiffThreshold,
114		})
115		if err != nil && settings.DryRun {
116			return err
117		}
118	
119		for _, r := range result.Results {
120			row := types.NewRow(
121				types.MRP("mode", r.Mode),
122				types.MRP("status", r.Status),
123				types.MRP("message", r.Message),
124			)
125			if err := gp.AddRow(ctx, row); err != nil {
126				return err
127			}
128		}
129	
130		if !settings.DryRun {
131			if containsMode(modesList, "capture") {
132				if err := emitCoverageRows(ctx, gp, cfg.Output.Dir); err != nil {
133					return err
134				}
135			}
136			if containsMode(modesList, "story-discovery") {
137				if err := emitStoryRows(ctx, gp, cfg.Output.Dir); err != nil {
138					return err
139				}
140			}
141		}
142	
143		return err
144	}
