146	func joinModes(modes []string) string {
147		out := ""
148		for i, m := range modes {
149			if i == 0 {
150				out = m
151				continue
152			}
153			out += "," + m
154		}
155		return out
156	}
157	
158	func containsMode(modesList []string, value string) bool {
159		for _, m := range modesList {
160			if m == value {
161				return true
162			}
163		}
164		return false
165	}
