167	func emitCoverageRows(ctx context.Context, gp middlewares.Processor, outDir string) error {
168		data, err := os.ReadFile(filepath.Join(outDir, "capture.json"))
169		if err != nil {
170			return err
171		}
172		var capture modes.CaptureResult
173		if err := json.Unmarshal(data, &capture); err != nil {
174			return err
175		}
176		row := types.NewRow(
177			types.MRP("type", "coverage"),
178			types.MRP("total", capture.Coverage.Total),
179			types.MRP("original_missing", capture.Coverage.OriginalMissing),
180			types.MRP("react_missing", capture.Coverage.ReactMissing),
181			types.MRP("original_hidden", capture.Coverage.OriginalHidden),
182			types.MRP("react_hidden", capture.Coverage.ReactHidden),
183		)
184		return gp.AddRow(ctx, row)
185	}
