190			return err
191		}
192		var stories modes.StoryDiscoveryResult
193		if err := json.Unmarshal(data, &stories); err != nil {
194			return err
195		}
196		for _, entry := range stories.Entries {
197			row := types.NewRow(
198				types.MRP("type", "story"),
199				types.MRP("id", entry.ID),
200				types.MRP("title", entry.Title),
201				types.MRP("name", entry.Name),
202			)
203			if err := gp.AddRow(ctx, row); err != nil {
204				return err
205			}
206		}
207		return nil
208	}
