 82	func Load(path string) (*Config, error) {
 83		data, err := os.ReadFile(path)
 84		if err != nil {
 85			return nil, err
 86		}
 87		var cfg Config
 88		if err := yaml.Unmarshal(data, &cfg); err != nil {
 89			return nil, err
 90		}
 91		if err := cfg.Validate(); err != nil {
 92			return nil, err
 93		}
 94		cfg.normalizeOutput(path)
 95		return &cfg, nil
