 98	func (c *Config) Validate() error {
 99		var errs []string
100		if strings.TrimSpace(c.Metadata.Slug) == "" {
101			errs = append(errs, "metadata.slug is required")
102		}
103		if strings.TrimSpace(c.Original.URL) == "" {
104			errs = append(errs, "original.url is required")
105		} else if err := validateURL(c.Original.URL); err != nil {
106			errs = append(errs, fmt.Sprintf("original.url invalid: %v", err))
107		}
108		if strings.TrimSpace(c.React.URL) == "" {
109			errs = append(errs, "react.url is required")
110		} else if err := validateURL(c.React.URL); err != nil {
111			errs = append(errs, fmt.Sprintf("react.url invalid: %v", err))
112		}
113		if strings.TrimSpace(c.Output.Dir) == "" {
114			errs = append(errs, "output.dir is required")
115		}
116		for i, s := range c.Sections {
117			if strings.TrimSpace(s.Name) == "" {
118				errs = append(errs, fmt.Sprintf("sections[%d] must include name", i))
119				continue
120			}
121			if strings.TrimSpace(s.Selector) == "" && strings.TrimSpace(s.SelectorOriginal) == "" && strings.TrimSpace(s.SelectorReact) == "" {
122				errs = append(errs, fmt.Sprintf("sections[%d] must include selector or selector_original/selector_react", i))
123				continue
124			}
125			if strings.TrimSpace(s.Selector) == "" {
126				if strings.TrimSpace(s.SelectorOriginal) == "" || strings.TrimSpace(s.SelectorReact) == "" {
127					errs = append(errs, fmt.Sprintf("sections[%d] must include both selector_original and selector_react when selector is omitted", i))
128				}
129			}
130		}
131		for i, s := range c.Styles {
132			if strings.TrimSpace(s.Name) == "" {
133				errs = append(errs, fmt.Sprintf("styles[%d] must include name", i))
134				continue
135			}
136			if strings.TrimSpace(s.Selector) == "" && strings.TrimSpace(s.SelectorOriginal) == "" && strings.TrimSpace(s.SelectorReact) == "" {
137				errs = append(errs, fmt.Sprintf("styles[%d] must include selector or selector_original/selector_react", i))
138				continue
139			}
140			if strings.TrimSpace(s.Selector) == "" {
141				if strings.TrimSpace(s.SelectorOriginal) == "" || strings.TrimSpace(s.SelectorReact) == "" {
142					errs = append(errs, fmt.Sprintf("styles[%d] must include both selector_original and selector_react when selector is omitted", i))
143				}
144			}
145		}
146		if len(errs) > 0 {
147			return errors.New(strings.Join(errs, "; "))
148		}
149		return nil
150	}
