153		if c.Output.Dir == "" {
154			return
155		}
156		if filepath.IsAbs(c.Output.Dir) {
157			return
158		}
159		base := filepath.Dir(configPath)
160		c.Output.Dir = filepath.Join(base, c.Output.Dir)
161	}
