 12	type ModeResult struct {
 13		Mode    string
 14		Status  string
 15		Message string
 16	}
 17	
 18	type RunResult struct {
 19		Results []ModeResult
 20	}
 21	
 22	type RunOptions struct {
 23		PixelDiffThreshold int
 24	}
 25	
 26	var defaultModes = []string{"capture", "cssdiff"}
 27	
 28	func NormalizeModes(raw string) ([]string, error) {
 29		raw = strings.TrimSpace(raw)
 30		if raw == "" {
 31			return defaultModes, nil
 32		}
 33		parts := strings.Split(raw, ",")
 34		var modesOut []string
 35		seen := map[string]bool{}
 36		for _, p := range parts {
 37			m := strings.TrimSpace(p)
 38			if m == "" {
 39				continue
 40			}
 41			if m == "full" {
 42				for _, fullMode := range []string{"capture", "pixeldiff", "cssdiff", "matched-styles", "ai-review"} {
 43					if !seen[fullMode] {
 44						modesOut = append(modesOut, fullMode)
 45						seen[fullMode] = true
 46					}
 47				}
 48				continue
 49			}
 50			if !seen[m] {
 51				modesOut = append(modesOut, m)
 52				seen[m] = true
 53			}
 54		}
 55		if len(modesOut) == 0 {
 56			return nil, fmt.Errorf("no modes provided")
 57		}
 58		return modesOut, nil
 59	}
 60	
 61	func Run(ctx context.Context, cfg *config.Config, modesList []string, dryRun bool, options RunOptions) (RunResult, error) {
 62		results := RunResult{}
 63		if dryRun {
 64			for _, m := range modesList {
 65				results.Results = append(results.Results, ModeResult{Mode: m, Status: "skipped", Message: "dry-run"})
 66			}
 67			return results, nil
 68		}
 69	
 70		for _, mode := range modesList {
 71			var err error
 72			switch mode {
 73			case "capture":
 74				err = modes.Capture(ctx, cfg)
 75			case "pixeldiff":
 76				threshold := options.PixelDiffThreshold
 77				if threshold == 0 {
 78					threshold = 30
 79				}
 80				err = modes.PixelDiff(ctx, cfg, threshold)
 81			case "cssdiff":
 82				err = modes.CSSDiff(ctx, cfg)
 83			case "matched-styles":
 84				err = modes.MatchedStyles(ctx, cfg)
 85			case "story-discovery":
 86				err = modes.StoryDiscovery(ctx, cfg)
 87			case "ai-review":
 88				err = modes.AIReview(ctx, cfg)
 89			default:
 90				err = fmt.Errorf("unknown mode: %s", mode)
 91			}
 92			if err != nil {
 93				results.Results = append(results.Results, ModeResult{Mode: mode, Status: "error", Message: err.Error()})
 94				return results, err
 95			}
 96			results.Results = append(results.Results, ModeResult{Mode: mode, Status: "ok", Message: "completed"})
 97		}
 98	
 99		return results, nil
100	}

