 25	func NewBrowser(parent context.Context) (*Browser, error) {
 26		log.Info().Msg("css-visual-diff chromedp: initializing browser")
 27		allocCtx, allocCancel := chromedp.NewExecAllocator(parent, chromedp.Headless, chromedp.NoFirstRun, chromedp.NoDefaultBrowserCheck)
 28		browserCtx, browserCancel := chromedp.NewContext(allocCtx)
 29		log.Info().Msg("css-visual-diff chromedp: browser context created")
 30		return &Browser{
 31			allocCtx:      allocCtx,
 32			allocCancel:   allocCancel,
 33			browserCtx:    browserCtx,
 34			browserCancel: browserCancel,
 35		}, nil
 36	}
