 38	func (b *Browser) Close() {
 39		log.Info().Msg("css-visual-diff chromedp: closing browser")
 40		if b.browserCancel != nil {
 41			b.browserCancel()
 42		}
 43		if b.allocCancel != nil {
 44			b.allocCancel()
 45		}
 46	}
