 31	func RunAIReview(ctx context.Context, cfg *config.Config) error {
 32		capturePath := filepath.Join(cfg.Output.Dir, "capture.json")
 33		data, err := os.ReadFile(capturePath)
 34		if err != nil {
 35			return fmt.Errorf("ai-review requires capture.json: %w", err)
 36		}
 37	
 38		var capture CaptureResult
 39		if err := json.Unmarshal(data, &capture); err != nil {
 40			return err
 41		}
 42	
 43		client := ai.NoopClient{}
 44		result := AIReviewResult{}
 45	
 46		for i, section := range cfg.Sections {
 47			if section.OCRQuestion == "" {
 48				continue
 49			}
 50	
 51			review := AISectionReview{
 52				Name:     section.Name,
 53				Selector: section.Selector,
 54				Question: section.OCRQuestion,
 55			}
 56	
 57			if i < len(capture.Original.Sections) {
 58				origShot := capture.Original.Sections[i].Screenshot
 59				review.Original.Screenshot = origShot
 60				ans, err := client.AnswerQuestion(ctx, origShot, section.OCRQuestion)
 61				if err != nil {
 62					ans.Error = err.Error()
 63				}
 64				review.Original.Answer = ans
 65			}
 66			if i < len(capture.React.Sections) {
 67				reactShot := capture.React.Sections[i].Screenshot
 68				review.React.Screenshot = reactShot
 69				ans, err := client.AnswerQuestion(ctx, reactShot, section.OCRQuestion)
 70				if err != nil {
 71					ans.Error = err.Error()
 72				}
 73				review.React.Answer = ans
 74			}
 75	
 76			result.Sections = append(result.Sections, review)
 77		}
 78	
 79		if cfg.Output.WriteJSON {
 80			if err := writeJSON(filepath.Join(cfg.Output.Dir, "ai-review.json"), result); err != nil {
 81				return err
 82			}
 83		}
 84		if cfg.Output.WriteMarkdown {
 85			if err := writeAIMarkdown(filepath.Join(cfg.Output.Dir, "ai-review.md"), result); err != nil {
 86				return err
 87			}
 88		}
 89	
 90		return nil
 91	}
