340	func writePixelDiffImages(url1Path, url2Path, diffComparisonPath, diffOnlyPath string, threshold int) (PixelDiffStats, error) {
341		img1, err := readPNG(url1Path)
342		if err != nil {
343			return PixelDiffStats{}, err
344		}
345		img2, err := readPNG(url2Path)
346		if err != nil {
347			return PixelDiffStats{}, err
348		}
349	
350		n1, n2 := padToSameSize(img1, img2)
351		stats, diffOnly := computePixelDiff(n1, n2, threshold)
352		stats.DiffComparisonPath = diffComparisonPath
353		stats.DiffOnlyPath = diffOnlyPath
354	
355		if err := writePNG(diffOnlyPath, diffOnly); err != nil {
356			return PixelDiffStats{}, err
357		}
358	
359		diffComparison := combineSideBySide(n1, n2, diffOnly)
360		if err := writePNG(diffComparisonPath, diffComparison); err != nil {
361			return PixelDiffStats{}, err
362		}
363	
364		return stats, nil
365	}

