 75	func (s Specificity) Compare(other Specificity) int {
 76		if s.A != other.A {
 77			if s.A > other.A {
 78				return 1
 79			}
 80			return -1
 81		}
 82		if s.B != other.B {
 83			if s.B > other.B {
 84				return 1
 85			}
 86			return -1
 87		}
 88		if s.C != other.C {
 89			if s.C > other.C {
 90				return 1
 91			}
 92			return -1
 93		}
 94		return 0
 95	}
