478	func originFromRule(ruleMatch *css.RuleMatch) CascadeOrigin {
479		if ruleMatch == nil || ruleMatch.Rule == nil {
480			return OriginAuthor
481		}
482		switch ruleMatch.Rule.Origin {
483		case css.StyleSheetOriginUserAgent:
484			return OriginUserAgent
485		case css.StyleSheetOriginRegular, css.StyleSheetOriginInjected, css.StyleSheetOriginInspector:
486			return OriginAuthor
487		default:
488			return OriginAuthor
489		}
490	}
